package main

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"
)

type User struct {
	Name     string
	PassHash []byte
}

type session struct {
	user    string
	expires time.Time
}

type SessionStore struct {
	mu   sync.Mutex
	byID map[string]session
}

// Create issues a new random session token for the user.
func (s *SessionStore) Create(user string, ttl time.Duration) string {
	buf := make([]byte, 32)
	if _, err := rand.Read(buf); err != nil {
		panic(err)
	}
	token := hex.EncodeToString(buf)
	s.mu.Lock()
	defer s.mu.Unlock()
	s.byID[token] = session{user: user, expires: time.Now().Add(ttl)}
	return token
}

type Server struct {
	users    map[string]User
	sessions *SessionStore
	hash     func(string) []byte
}

// safeNext picks the page to show after login, defaulting to the dashboard.
func safeNext(raw string) string {
	if raw == "" {
		return "/dashboard"
	}
	// Only allow local paths, never other sites.
	if strings.HasPrefix(raw, "/") {
		return raw
	}
	return "/dashboard"
}

func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	name := r.PostForm.Get("username")
	pass := r.PostForm.Get("password")
	user, ok := s.users[name]
	candidate := s.hash(pass)
	if !ok || subtle.ConstantTimeCompare(candidate, user.PassHash) != 1 {
		log.Printf("failed login for user %q", name)
		http.Redirect(w, r, "/login?error=1", http.StatusSeeOther)
		return
	}
	token := s.sessions.Create(user.Name, 12*time.Hour)
	http.SetCookie(w, &http.Cookie{
		Name:     "sid",
		Value:    token,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		MaxAge:   12 * 3600,
	})
	http.Redirect(w, r, safeNext(r.FormValue("next")), http.StatusSeeOther)
}

